mapper.select:
/*selectSellerMpIvObtnodrReceiptList*/ SELECT Y.STATUS , Y.GUBUN , Y.DESCRIPTION , Y.SPECIFICATION , Y.MAKER_NAME , Y.ITEM_NO , Y.ADD_DATE FROM ( SELECT DECODE(A.STATUS, 'S', '요청', 'C', '게시', 'B', '반려', 'R','게시', 'A','보관','D','삭제','V','추천') AS STATUS , DECODE(A.ITEM_FLAG, 'N', '일반', 'G','기획') AS GUBUN , A.DESCRIPTION AS DESCRIPTION , A.SPECIFICATION AS SPECIFICATION , A.MAKER_NAME AS MAKER_NAME , A.ITEM_NO AS ITEM_NO , A.ADD_DATE FROM PRMTITEM A WHERE A.AGENT= #{st_com_code}
AND A.ITEM_NO LIKE '%'||#{st_list_item_no}||'%'
AND A.DESCRIPTION LIKE '%'||#{st_list_description}||'%'
AND A.SPECIFICATION LIKE '%'||#{st_list_specification}||'%'
AND A.MAKER_NAME LIKE '%'||#{st_list_maker_name}||'%'
AND A.ITEM_FLAG = #{st_list_item_flag}
AND DECODE(A.STATUS, 'S', '요청', 'C', '게시', 'B', '반려', 'R','게시', 'A','보관','D','삭제','V','추천') = #{st_list_status}
) Y ORDER BY Y.ADD_DATE DESC
